E["110:083ee81d"] = "Mastercraft працює з цими аддонами, якщо вони встановлені, - жодного їхнього файлу він не містить. Дякуємо!"
E["110:5b03f717"] = "Невеликий посібник лише з вашим поточним кроком. Стоїть поруч із вікном професій - перетягніть куди завгодно."
E["110:a2bef2c4"] = "Точки руди й трав, які ви збираєте, запам'ятовуються для всіх ваших персонажів і показуються на карті та мінікарті."
E["110:be208f5b"] = "|cffeef0f5/mc new|r  що нового      |cffeef0f5/mc errors|r  звіт про помилки      |cffeef0f5/mc donate|r  підтримка"
E["110:efdcde81"] = "Код для безкоштовного списку майстрів getmastercraft.com - ви вставляєте його на сайті. Саме нічого не надсилається."
E["111:65324ce4"] = "Вставляє готовий рядок із предметом у поле чату для каналу «Торгівля». Нічого не надсилається, доки ви не натиснете Enter."
E["111:d63150b4"] = "Маршрут Forever. Білування - природний напарник. Вичиняйте власні шкури. Деякі кроки потребують креслення від торговця або за завдання."
E["113:126e6bff"] = "Коли ваші ціни старші за цей час, Mastercraft нагадує просканувати - під час входу в гру й на аукціоні."
E["113:e18a8678"] = "Маршрут Forever. Флакони продають торговці алхімічними й торговельними припасами. Травництво - ідеальна додаткова професія."
E["113:f6b57c38"] = "Сканування цін зупинено - на аукціоні виконано інший пошук, тому нічого не збережено. Натисніть «Сканувати ціни» ще раз."
E["114:037ce8f7"] = "Mastercraft розмовляє англійською, німецькою та грецькою. Оберіть свою мову кнопкою з глобусом угорі праворуч або введіть /mc lang."
E["114:6dccb557"] = "Одну дію довелося відкласти - нічого не втрачено. Якщо це повторюватиметься, |cffffd140/mc errors|r дасть вам текст для нас."
E["114:7e1c3aad"] = "2. Натисніть «Імпортувати точки». Mastercraft одноразово копіює точки руди й трав - спершу імпортувати в GatherMate2 не потрібно."
E["114:88284f58"] = "Маршрут Forever. Гірнича справа - природний напарник. Виготовляйте шліфувальні камені самі - шорсткі й вищі не дають підвищення уміння."
E["114:a388110d"] = "Шукає все, що вам ще потрібно, і зберігає це як список покупок «Mastercraft» на вкладці покупок Auctionator."
E["115:9910bd04"] = "Виставлення забирає час і може не продатися - аукціон радять, лише коли він платить явно більше, ніж торговець."
E["116:53a504f4"] = "З контролером рядок чату не відкривається - після цього гра заблокувала б кнопки вашого контролера."
E["117:00d4498b"] = "Клацніть, щоб перемкнути: під час збору («Пошук Мінералів» або «Пошук трав» увімкнено - не в містах, підземеллях чи бою), завжди або вимкнено."
E["117:047f583c"] = "Слова або назви предметів, розділені комою. Допис з одним із них відтворює звук, показує спливне вікно і стає золотим тут."
E["117:bc97d8ed"] = "Цього разу також кладе в банк те, що залишається у ваших сумках. Перемикачі «Залишати» на кнопці спорядження щоразу визначають, що залишається."
E["117:c861e3d4"] = "Клацання «Увімкнути» чи кнопки закриття на нагадуванні «Пошук Мінералів» / «Пошук трав» більше не змушує головне вікно стрибати."
E["117:d8ef2bdf"] = "Кожен рецепт у трекері предметів має - / + на назві: задайте, скільки хочете виготовити, і всі його матеріали підлаштуються."
E["118:0c05c29b"] = "Крок 1: читає весь аукціон одразу - найнижчу ціну кожного предмета і скільки їх виставлено. Кілька секунд."
E["119:1ffceca9"] = "Четвертий вигляд у Налаштування > Стиль: Північ - майже чорний із м'яким фіолетовим сяйвом, приємний для очей. Оберіть його й перезавантажте."
E["119:59cb0d40"] = "Маршрут Forever. Гірнича справа - природний напарник. Виготовляйте деталі самі: болти, трубки, вибуховий порошок, корпуси й запали."
E["119:5efede6d"] = "Переплавляйте руду на кузні по дорозі - відкритий крок перелічує плавки, що дають очки вміння. Самоцвіти - рідкісні додаткові знахідки."
